:root {
  --paper: #ffffff;
  --panel: #f2f5f8;
  --ink: #1c2733;
  --ink-soft: #4b5765;
  --ink-faint: #76818d;
  --rule: #d6dce3;
  --council: #1f4e79;
  --council-deep: #163a5c;
  --marker: #ffe24d;
  --marker-soft: #fff4b8;
  --checked: #2a7a58;
  --checked-soft: #e4f3ec;
  --doc-paper: #fbfaf5;

  --font-text: Charter, "Bitstream Charter", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --font-doc: "Courier New", Courier, "Courier 10 Pitch", "Nimbus Mono PS", monospace;

  --measure: 62ch;
  --wrap: 1120px;
  --gutter: 20px;
  --radius: 4px;
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition: none !important; animation: none !important; }
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-text);
  font-size: 1.0625rem;
  line-height: 1.6;
  font-kerning: normal;
}

img, svg { display: block; max-width: 100%; }

a { color: var(--council); text-decoration-thickness: 1px; text-underline-offset: 0.14em; }
a:hover { color: var(--council-deep); }

:focus-visible {
  outline: 3px solid var(--council);
  outline-offset: 3px;
}

h1, h2, h3 { margin: 0; line-height: 1.15; font-weight: 700; letter-spacing: -0.012em; }
h1 { font-size: clamp(2rem, 1.2rem + 3.2vw, 3.4rem); line-height: 1.08; }
h2 { font-size: clamp(1.55rem, 1.1rem + 1.7vw, 2.2rem); }
h3 { font-size: 1.2rem; }
p { margin: 0 0 1em; }
p:last-child { margin-bottom: 0; }

.wrap {
  width: min(100% - 2 * var(--gutter), var(--wrap));
  margin-inline: auto;
}

.skip-link {
  position: absolute; left: var(--gutter); top: -60px;
  background: var(--ink); color: #fff; padding: 8px 12px; border-radius: var(--radius);
  z-index: 10;
}
.skip-link:focus { top: 8px; }

.visually-hidden {
  position: absolute !important; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap;
}

/* ----- Header ----- */
.site-header {
  border-bottom: 1px solid var(--rule);
  background: var(--paper);
}
.site-header .wrap {
  display: flex; align-items: center; justify-content: space-between;
  gap: 16px; min-height: 68px; flex-wrap: wrap; padding-block: 10px;
}
.wordmark {
  display: inline-flex; align-items: baseline; gap: 10px;
  color: var(--ink); text-decoration: none; font-weight: 700; font-size: 1.3rem;
}
.wordmark .mark {
  display: inline-block; width: 1.05em; height: 0.62em; align-self: center;
  background: var(--marker); border-radius: 2px;
  box-shadow: inset 0 -0.18em 0 var(--council);
}
